 /// Saturate a microsecond count into a deadline key.
+// Instant's entire domain is u64 nanoseconds from this origin.
+fn nanos(at: crate::time::Instant) -> u64 {
+	at.duration_since(crate::time::Instant::ZERO)
+		.as_nanos()
+		.try_into()
+		.expect("instant fits u64 nanoseconds")
+}
+
 fn micros(value: u128) -> u64 {
 	value.try_into().unwrap_or(u64::MAX)
 }
